INSERT INTO "ToolRegistryEntry" ("id", "tool_id", "label", "label_hi", "text", "chat_guidable", "kind", "summary", "summary_hi", "section", "therapy_modality", "therapist_note", "access_mode", "load_level", "est_minutes", "content_en", "content_hi", "status", "approved_at", "sort_order", "library_group", "care_plans", "sensitive_check", "updated_at") VALUES
    ('c1b2a3d4-0000-4e00-9000-000000000fa1', 'ws_body_map', 'Body map', NULL, 'Mark where in the body a feeling shows up, and how strong it is there.', false, 'worksheet', 'Mark where in the body a feeling shows up, and how strong it is there.', NULL, 'notice_and_name', 'Interoceptive awareness (body scan, somatic mapping)', 'the client taps the parts of the outline where something is present, then picks feelings for each tapped part and rates how strong it is there. Per part, never a total — two places can carry different feelings and the exercise is about noticing that.', 'open', 'light', 5, $ws_ws_body_map${"version":1,"intro":"Feelings show up in the body before we have words for them — a tight chest, a heavy stomach, shoulders up by the ears. Tap wherever you notice something today. There's no right place to find.","fields":[{"id":"where","type":"body_outline","prompt":"Where do you notice something right now?","helper":"Tap as many places as fit, up to three. Nothing has to be there.","required":true,"maxSelections":3,"withStrength":true,"strengthPrompt":"How strong is it there?","withFeelings":true,"feelingsPrompt":"What does it feel like there?","feelings":[{"id":"sad","label":"sad"},{"id":"scared","label":"scared"},{"id":"angry","label":"angry"},{"id":"ashamed","label":"ashamed"},{"id":"happy","label":"happy"},{"id":"calm","label":"calm"},{"id":"numb","label":"numb"},{"id":"worried","label":"worried","parent":"scared"},{"id":"panicky","label":"panicky","parent":"scared"},{"id":"unsafe","label":"unsafe","parent":"scared"},{"id":"on_edge","label":"on edge","parent":"scared"}],"regions":[{"id":"head","label":"Head"},{"id":"face","label":"Face"},{"id":"jaw","label":"Jaw"},{"id":"throat","label":"Throat"},{"id":"neck","label":"Neck"},{"id":"shoulders","label":"Shoulders"},{"id":"chest","label":"Chest"},{"id":"heart","label":"Heart"},{"id":"stomach","label":"Stomach"},{"id":"belly","label":"Belly"},{"id":"back","label":"Back"},{"id":"arms","label":"Arms"},{"id":"hands","label":"Hands"},{"id":"hips","label":"Hips"},{"id":"legs","label":"Legs"},{"id":"knees","label":"Knees"},{"id":"feet","label":"Feet"}]}],"closing":{"text":"You noticed where it lives. That is often the first step to it easing."}}$ws_ws_body_map$::jsonb, NULL, 'draft', NULL, 130, NULL, ARRAY['all']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000fa2', 'ws_sleep_diary', 'Sleep diary', NULL, 'Record sleep and wake times and how the day felt, to spot a pattern.', false, 'worksheet', 'Record sleep and wake times and how the day felt, to spot a pattern.', NULL, 'energy_life', 'Sleep hygiene monitoring (self-report diary)', 'bedtime, wake time, restedness, screens before bed and a short note, one entry per night. No medicine field by the owner''s rule — sleep medication is a prescriber decision and is not asked about here.', 'open', 'light', 3, $ws_ws_sleep_diary${"version":1,"intro":"Sleep and mood pull on each other, and it's hard to see the pattern from inside a tired week. A short note each morning is enough — this isn't a test, and a bad night is still useful information.","fields":[{"id":"night","type":"datetime","prompt":"Which night is this?","helper":"The night you are writing about.","required":true,"withDate":true,"withTime":false},{"id":"bedtime","type":"datetime","prompt":"What time did you get into bed?","withDate":false,"withTime":true},{"id":"wake_time","type":"datetime","prompt":"What time did you get up?","helper":"Getting up, not waking — they are often different.","withDate":false,"withTime":true},{"id":"rested","type":"scale_0_10","prompt":"How rested do you feel today?","minLabel":"not at all rested","maxLabel":"very rested"},{"id":"screens","type":"choice","prompt":"Were you on a screen in the hour before bed?","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}]},{"id":"notes","type":"short_text","prompt":"Anything worth noting about last night?","helper":"Waking in the night, a racing mind, a late message, something on your mind. A few words is enough."}],"closing":{"text":"One night is a data point, not a verdict. The pattern is what helps."}}$ws_ws_sleep_diary$::jsonb, NULL, 'draft', NULL, 140, NULL, ARRAY['all']::TEXT[], true, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000fa3', 'ws_muscle_relaxation', 'Muscle relaxation', NULL, 'Tense and release each part of the body in turn, guided step by step.', false, 'worksheet', 'Tense and release each part of the body in turn, guided step by step.', NULL, 'calm_my_body', 'Progressive muscle relaxation', 'guided tense-and-release through the main muscle groups. Audio-guided once the owner approves the script and the voice; until then the script is read on screen and nothing is recorded.', 'open', 'light', 10, $ws_ws_muscle_relaxation${"version":1,"intro":"When the body holds tension for a long time, it stops noticing it. This is a few minutes of tensing each part gently, then letting it go — so the difference becomes something you can feel again. Nothing here should hurt. If a part is injured, skip it.","fields":[{"id":"settle","type":"instruction","prompt":"Sit or lie somewhere comfortable. Let your hands rest. Take one slow breath out, and let your shoulders drop."},{"id":"hands_arms","type":"instruction","prompt":"Make a loose fist with both hands and gently tighten your arms. Hold for a moment — not hard, just enough to feel it. Now let go completely. Notice the difference for a few seconds."},{"id":"shoulders_neck","type":"instruction","prompt":"Lift your shoulders towards your ears and hold them there. Then let them fall. Feel how far down they go when you stop holding them."},{"id":"face","type":"instruction","prompt":"Scrunch your face gently — eyes, jaw, forehead. Hold, then release. Let your jaw come slightly apart."},{"id":"stomach","type":"instruction","prompt":"Tighten your stomach muscles gently, as if bracing. Hold, then let them soften. Let your breath go low into your belly."},{"id":"legs_feet","type":"instruction","prompt":"Point your toes away and tighten your legs. Hold, then release. Let your legs feel heavy where they are."},{"id":"whole_body","type":"instruction","prompt":"Now the whole body at once, gently. Hold for a moment, then let everything go and breathe out slowly."},{"id":"after","type":"scale_0_10","prompt":"How does your body feel now?","minLabel":"still tense","maxLabel":"much softer"}],"closing":{"text":"You don't have to carry it all in your muscles. Come back to this whenever the tension builds."}}$ws_ws_muscle_relaxation$::jsonb, NULL, 'draft', NULL, 150, NULL, ARRAY['all']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000fa4', 'ws_safe_place', 'Safe place', NULL, 'Build a calm place in your mind, guided, to return to when things feel too much.', false, 'worksheet', 'Build a calm place in your mind, guided, to return to when things feel too much.', NULL, 'calm_my_body', 'Guided imagery (safe place)', 'guided imagery to a place the client builds themselves. Audio-guided once the owner approves the script and the voice; until then the script is read on screen and nothing is recorded. The place is the client''s own — nothing is suggested for them.', 'open', 'light', 10, $ws_ws_safe_place${"version":1,"intro":"Somewhere in your mind there is a place that feels calmer than here. It can be real or made up, somewhere you have been or somewhere you would like to be. We're going to spend a few minutes there.","fields":[{"id":"settle","type":"instruction","prompt":"Sit or lie somewhere comfortable. Let your eyes close if that feels alright, or soften your gaze. Take one slow breath out."},{"id":"choose","type":"short_text","prompt":"Where is your place?","helper":"A room, a beach, a hill, a corner of someone's house, somewhere you invent. A few words is enough.","required":true},{"id":"see","type":"instruction","prompt":"Picture it now. What can you see there — colours, light, the shape of things? Take a moment to look around it slowly."},{"id":"hear","type":"instruction","prompt":"What can you hear in this place? Maybe it is quiet. Let the sounds be there without needing to change them."},{"id":"feel","type":"instruction","prompt":"What does it feel like on your skin — the air, the ground under you, the temperature? Let yourself settle into that."},{"id":"stay","type":"instruction","prompt":"Stay here a little longer. Nothing is needed from you in this place. When you are ready, take one slow breath and come back."},{"id":"after","type":"scale_0_10","prompt":"How do you feel now?","minLabel":"still unsettled","maxLabel":"calmer"}],"closing":{"text":"This place is yours. You can come back to it whenever you need somewhere to put yourself down."}}$ws_ws_safe_place$::jsonb, NULL, 'draft', NULL, 160, NULL, ARRAY['all']::TEXT[], false, CURRENT_TIMESTAMP)
